   Exemplo de Yaf_View_Simple::display


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        $this->getView()->assign("title", "My Homepage");

        /* renderiza index/index.phtml e armazena o resultado
         * no corpo da resposta */
        $this->getView()->display("index/index.phtml");

        return false; // a renderização foi feita manualmente; ignora a renderização automática
    }
}
?>




